 BL","checked_at":"2026-11-17","locator":"Das Theater; usos y restauración"}],"source_url":"https://www.augustaraurica.ch/besuchen/theater","source_title":"Augusta Raurica · Teatro","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":false,"next_review_at":"2027-11-17","concept_id":"BL:teatro-anfiteatro-bl","status":"published","editorial_difficulty":"media","game_only":true,"correct_index":0},"known":["629b1d5291bdba89f6f458e40a0ef9ea"]},{"question":{"id":"szx-bl-tesoro-comprobar","collection":"suizamente-integration-1350-v1","territory":"BL","scope":"canton","canton":"BL","topic":"cultura","category":"sociedad","difficulty":3,"language":"es","game_type":"tf","prompt":"Antes de ir a Augusta Raurica solo para ver el tesoro de plata, conviene comprobar si está expuesto.","options":["Verdadero","Falso"],"explanation":"La página consultada avisa de que no está expuesto actualmente. Que una colección exista no garantiza que todas sus piezas estén en sala.","sources":[{"id":"bl-silver-17","url":"https://www.augustaraurica.ch/besuchen/silberschatz","title":"Augusta Raurica · Tesoro de plata","authority":"Augusta Raurica, Bildungs-, Kultur- und Sportdirektion BL","checked_at":"2026-11-17","locator":"Descripción; Fundgeschichte"}],"source_url":"https://www.augustaraurica.ch/besuchen/silberschatz","source_title":"Augusta Raurica · Tesoro de plata","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":true,"next_review_at":"2027-02-17","concept_id":"BL:tesoro-comprobar","status":"published","editorial_difficulty":"media","game_only":true,"correct_index":0,"editorial_review":{"date":"2026-11-18","revision":"complete-14","kind":"wording-and-interaction"}},"known":["9209515ed357d8b78958f9eb9d172587"]},{"question":{"id":"szx-bl-teatro-vivo-bl","collection":"suizamente-integration-1350-v1","territory":"BL","scope":"canton","canton":"BL","topic":"cultura","category":"soci